#include <gtest/gtest.h>
#include "data/kv_snapshot_codec.h"
TEST(KVSnapshotCodecTest, StableRoundTripAndBoundedDecode){base::KVRequestSnapshot s;s.block_size=16;s.num_layers=1;s.valid_tokens=16;s.committed_tokens=16;s.layers.resize(1);s.layers[0].storage_mode=base::BlockStorageMode::kPlain;s.layers[0].storage_dtype=base::DataType::kDataTypeBf16;s.layers[0].blocks.resize(1);s.layers[0].blocks[0].key={1,2};s.layers[0].blocks[0].value={3,4};std::vector<uint8_t>b;ASSERT_EQ(data::EncodeKVSnapshot(s,&b),data::DataError::kOk);base::KVRequestSnapshot x;ASSERT_EQ(data::DecodeKVSnapshot(b.data(),b.size(),b.size(),&x),data::DataError::kOk);EXPECT_EQ(x.valid_tokens,16);EXPECT_EQ(x.layers[0].blocks[0].value,(std::vector<uint8_t>{3,4}));EXPECT_EQ(data::DecodeKVSnapshot(b.data(),b.size(),b.size()-1,&x),data::DataError::kInvalidArgument);}
